import WebSocket, { WebSocketServer } from "ws";
const server = new WebSocketServer({ host: "127.0.0.1", port: 8080, maxPayload: 1024 });
await new Promise(resolve => server.once("listening", resolve));
server.on("connection", socket => { socket.once("pong", () => socket.send("Still here")); socket.ping(); });
const client = new WebSocket("ws://127.0.0.1:8080");
client.on("message", data => { console.log(data.toString()); client.close(); server.close(); });
